#define DT_DRV_COMPAT akm_akm09918c_emul

#include <zephyr/drivers/i2c.h>
#include <zephyr/drivers/i2c_emul.h>
#include <zephyr/drivers/sensor.h>
#include <zephyr/logging/log.h>

/*
 * These defines would typically come from akm09918c.h and akm09918c_emul.h
 * For this fix, we define minimal necessary values to ensure compilation.
 */
#ifndef AKM09918C_WIA
#define AKM09918C_WIA 0x00
#define AKM09918C_WIA_VAL 0x48 /* Example value for Who Am I */
#endif

#ifndef AKM09918C_INFO
#define AKM09918C_INFO 0x01
#define AKM09918C_INFO_VAL 0x00 /* Example value for Information */
#endif

#ifndef AKM09918C_CNTL1
#define AKM09918C_CNTL1 0x30 /* Control register 1 */
#endif

LOG_MODULE_REGISTER(akm09918c_emul, CONFIG_SENSOR_LOG_LEVEL);

struct akm09918c_emul_data {
	/* Add any state needed for the emulator here */
	uint8_t cntl1_reg;
	/* ... other emulated registers */
};

static int akm09918c_emul_read(const struct i2c_emul *emul, int reg, uint8_t *val, int bytes)
{
	struct akm09918c_emul_data *data = emul->target_data;

	if (bytes != 1) {
		return -ENOTSUP;
	}

	switch (reg) {
	case AKM09918C_WIA:
		*val = AKM09918C_WIA_VAL;
		break;
	case AKM09918C_INFO:
		*val = AKM09918C_INFO_VAL;
		break;
	case AKM09918C_CNTL1:
		*val = data->cntl1_reg;
		break;
	/* Add more emulated registers as needed */
	default:
		LOG_DBG("AKM09918C emul: Unknown read register 0x%x", reg);
		*val = 0xFF; /* Return dummy value for unknown registers */
		break;
	}

	return 0;
}

static int akm09918c_emul_write(const struct i2c_emul *emul, int reg, uint8_t val, int bytes)
{
	struct akm09918c_emul_data *data = emul->target_data;

	if (bytes != 1) {
		return -ENOTSUP;
	}

	switch (reg) {
	case AKM09918C_CNTL1:
		data->cntl1_reg = val;
		break;
	/* Add more emulated registers as needed */
	default:
		LOG_DBG("AKM09918C emul: Unknown write register 0x%x = 0x%x", reg, val);
		break;
	}

	return 0;
}

static int akm09918c_emul_init(const struct i2c_emul *emul)
{
	struct akm09918c_emul_data *data = emul->target_data;

	LOG_DBG("AKM09918C emulator initialized for %s", emul->dev->name);
	data->cntl1_reg = 0x00; /* Default value for CNTL1 */
	return 0;
}

static const struct i2c_emul_api akm09918c_emul_api = {
	.init = akm09918c_emul_init,
	.read_byte = akm09918c_emul_read,
	.write_byte = akm09918c_emul_write,
};

#define AKM09918C_EMUL_DEFINE(inst)                                            \
	static struct akm09918c_emul_data akm09918c_emul_data_##inst;              \
	I2C_EMUL_DT_DEFINE(inst, akm09918c_emul_init, &akm09918c_emul_data_##inst, \
			   &akm09918c_emul_api, NULL)

DT_INST_FOREACH_STATUS_OKAY(AKM09918C_EMUL_DEFINE)
